with base as (select * from {{ ref('int_station_hourly_flow') }}), agg as (select station, sum(entries) as total_entries, sum(exits) as total_exits, sum(entries+exits) as total_footfall, sum(case when time_band='am_peak' then entries else 0 end) as am_entries, sum(case when time_band='am_peak' then exits else 0 end) as am_exits, sum(case when time_band='pm_peak' then entries else 0 end) as pm_entries, sum(case when time_band='pm_peak' then exits else 0 end) as pm_exits from base group by station) select *, am_entries*1.0/nullif(total_entries,0) as am_entry_share, am_exits*1.0/nullif(total_exits,0) as am_exit_share, pm_entries*1.0/nullif(total_entries,0) as pm_entry_share, pm_exits*1.0/nullif(total_exits,0) as pm_exit_share, ((am_exits-am_entries)+(pm_entries-pm_exits))*1.0/nullif(am_entries+am_exits+pm_entries+pm_exits,0) as employment_score, (am_entries+am_exits+pm_entries+pm_exits)*1.0/nullif(total_footfall,0) as peak_concentration from agg
